import fs from 'node:fs';
import path from 'node:path';

const ALWAYS_PASS_TEST_SITE_KEY = '1x00000000000000000000AA';
const configuredSiteKey = String(process.env.NG_APP_TURNSTILE_SITE_KEY || '').trim();
const isVercelProduction = process.env.VERCEL === '1' && process.env.VERCEL_ENV === 'production';
const siteKey = configuredSiteKey || (isVercelProduction ? '' : ALWAYS_PASS_TEST_SITE_KEY);

const outPath = path.resolve('src/environments/turnstile.env.ts');
const contents = [
  '// Generated by scripts/gen-turnstile-env.mjs. Do not add secrets here.',
  `export const TURNSTILE_SITE_KEY = ${JSON.stringify(siteKey)};`,
  '',
].join('\n');

fs.writeFileSync(outPath, contents);

if (!configuredSiteKey) {
  if (isVercelProduction) {
    console.warn('[turnstile] NG_APP_TURNSTILE_SITE_KEY is not set; public forms will remain unavailable.');
  } else {
    console.log('[turnstile] NG_APP_TURNSTILE_SITE_KEY not set; using Cloudflare\'s always-pass test sitekey.');
  }
}
